parameters.command:
python3 -c "
import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-contract-variant-wrappers/ContractVariantsBpmn/ContractVariantsBpmn.bpmn')
root = tree.getroot()
ns = {'bpmn':'http://www.omg.org/spec/BPMN/20100524/MODEL','bpmndi':'http://www.omg.org/spec/BPMN/20100524/DI','uipath':'http://uipath.org/schema/bpmn'}
proc = root.find('bpmn:process', ns)

# Check each task has exactly one incoming and one outgoing (linear chain)
for e in proc:
    inc = e.findall('bpmn:incoming', ns)
    out = e.findall('bpmn:outgoing', ns)
    tag = e.tag.split('}')[-1]
    eid = e.get('id','?')
    if tag in ('startEvent','endEvent','serviceTask','businessRuleTask','sendTask','receiveTask','callActivity','scriptTask','intermediateThrowEvent'):
        if tag == 'startEvent' and len(out) != 1: print(f'WARN {eid}: outgoing={len(out)}')
        if tag == 'endEvent' and len(inc) != 1: print(f'WARN {eid}: incoming={len(inc)}')
        if tag not in ('startEvent','endEvent'):
            if len(inc) != 1: print(f'WARN {eid}: incoming={len(inc)}')
            if len(out) != 1: print(f'WARN {eid}: outgoing={len(out)}')

# Check DI shapes list content
diag = root.find('bpmndi:BPMNDiagram', ns)
plane = diag.find('bpmndi:BPMNPlane', ns)
dc_ns = 'http://www.omg.org/spec/DD/20100524/DC'
for s in plane:
    tag = s.tag.split('}')[-1]
    if tag == 'BPMNShape':
        bounds = s.find('{%s}Bounds' % dc_ns)
        if bounds is None: print(f'Shape {s.get(\"bpmnElement\")} missing Bounds')

print('Structural check done.')
"
